/**
 * Pacing-engine contract (Track B implements in lib/engine/, pure + unit-tested).
 * See docs/design-plan.md §7.
 */
import type { LearningMomentInput, MomentType, Verdict } from "./moment";

export type Familiarity = "new" | "some" | "comfortable";
export type GuardrailMode = "light" | "balanced" | "strict";

export interface UserSettings {
  sound: boolean;
  volume: number; // 0..1
  theme: string; // theme id
  soundPack: string; // sound pack id
  guardrails: { enabled: boolean; mode: GuardrailMode };
}

export interface ConceptMastery {
  theta: number;
  n: number;
  lastSeen: number; // epoch ms
}
export type MasteryMap = Record<string, ConceptMastery>;

export interface Outcome {
  momentId: string;
  concept: string;
  type: MomentType | "boss";
  score: number; // 1 correct, 0.6 correct-after-MC, 0.5 partial, 0 incorrect
  at: number;
}

export type BossOutcome = "flawless" | "victory" | "retreat";
export interface BossRecord {
  id: string;
  startedAt: number;
  concepts: string[];
  outcome?: BossOutcome;
}

export interface EngineState {
  pendingMomentId?: string;
  momentsShownAt: number[]; // epoch ms of each shown moment
  turnsSinceMoment: number; // work turns since last shown moment
  conceptsSinceBoss: string[]; // distinct concepts practised since last boss
  bosses: BossRecord[];
  recentOutcomes: Outcome[]; // most recent last, capped (e.g. 20)
}

export const initialEngineState = (): EngineState => ({
  momentsShownAt: [],
  turnsSinceMoment: 0,
  conceptsSinceBoss: [],
  bosses: [],
  recentOutcomes: [],
});

export interface GateContext {
  state: EngineState;
  mastery: MasteryMap;
  settings: UserSettings;
  familiarity: Familiarity;
  now: number;
}

export type GateDecision =
  | { action: "show" }
  | { action: "defer"; reason: string }
  | { action: "skip"; reason: "one_at_a_time" | "low_value" | "mastered" | "off_band" | "cap" | "unverified" };

export type DifficultyKind = "first_exposure" | "practice" | "boss";

/** Engine summary rendered into the work model's dynamic context each turn. */
export interface EngineSummary {
  guardrails: { enabled: boolean; mode: GuardrailMode };
  valueThreshold: number;
  targetDifficulty: { firstExposure: number; practice: number }; // for a typical unseen/seen concept
  masteredConcepts: string[];
  conceptsSinceBoss: string[];
  rollingAccuracy: number | null; // over last 5 graded outcomes
  recentOutcomes: { concept: string; type: string; score: number }[]; // last 3
}

export type XpEvent =
  | { kind: "answer"; verdict: Verdict; afterMC: boolean }
  | { kind: "prediction"; verdict: Verdict }
  | { kind: "boss_hit"; partial: boolean }
  | { kind: "boss_outcome"; outcome: BossOutcome }
  | { kind: "session_complete" };

export interface LevelInfo {
  level: number;
  xp: number;
  levelStartXp: number;
  nextLevelXp: number;
}

export interface LevelReward {
  level: number;
  kind: "theme" | "sound_pack";
  id: string;
  label: string;
}

/** Signatures Track B must export from lib/engine/index.ts. */
export interface EngineApi {
  gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision;
  updateMastery(prev: ConceptMastery | undefined, score: number, difficulty: number, familiarity: Familiarity, now: number): ConceptMastery;
  targetDifficulty(m: ConceptMastery | undefined, kind: DifficultyKind, familiarity: Familiarity, recent: Outcome[]): number;
  isMastered(m: ConceptMastery | undefined): boolean;
  reviewDue(m: ConceptMastery | undefined, now: number): boolean;
  bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean;
  bossOutcome(hits: number, maxHits: number): BossOutcome;
  summarize(ctx: GateContext): EngineSummary;
  recordShown(state: EngineState, momentId: string, now: number): EngineState;
  recordOutcome(state: EngineState, outcome: Outcome): EngineState;
  recordWorkTurn(state: EngineState): EngineState;
  xpFor(event: XpEvent): number;
  levelFor(totalXp: number): LevelInfo;
  rewardsBetween(fromLevel: number, toLevel: number): LevelReward[];
}
/** Elo-lite mastery model (design-plan §7.3, principle P5). */
import type { ConceptMastery, Familiarity } from "@/lib/contracts/engine";
import type { Verdict } from "@/lib/contracts/moment";
import { clamp, sigmoid } from "./math";

/** Starting θ by self-reported familiarity (design-plan §7.3). */
export const INITIAL_THETA: Record<Familiarity, number> = { new: 1.5, some: 2.5, comfortable: 3.5 };

/** Slope of the logistic: P(correct) = σ(SLOPE·(θ − b)) (design-plan §7.3). */
export const SLOPE = 1.2;

/** Learning rate: fast while we know little about the learner, then slower (design-plan §7.3). */
export const K_EARLY = 0.6;
export const K_LATE = 0.3;
export const K_EARLY_ATTEMPTS = 3; // K_EARLY applies while n < this

/** θ bounds: one step beyond the 1–5 difficulty scale on each side. */
export const THETA_MIN = 0;
export const THETA_MAX = 6;

/** Mastered = enough attempts and P(correct at a medium question) ≥ threshold (design-plan §7.3). */
export const MASTERY_MIN_ATTEMPTS = 2;
export const MASTERY_REFERENCE_DIFFICULTY = 3;
export const MASTERY_P_THRESHOLD = 0.8;

/** A mastered concept unseen for longer than this resurfaces as review (design-plan §7.3). */
export const REVIEW_AFTER_MS = 24 * 60 * 60 * 1000;

/** Outcome scores (design-plan §7.3). Skipped answers have no score and never update mastery. */
export const SCORE = { correct: 1, correctAfterMC: 0.6, partial: 0.5, incorrect: 0 } as const;

export function scoreFor(verdict: Verdict, afterMC: boolean): number {
  if (verdict === "correct") return afterMC ? SCORE.correctAfterMC : SCORE.correct;
  return verdict === "partial" ? SCORE.partial : SCORE.incorrect;
}

export function thetaOf(m: ConceptMastery | undefined, familiarity: Familiarity): number {
  return m ? m.theta : INITIAL_THETA[familiarity];
}

export function pCorrect(theta: number, difficulty: number): number {
  return sigmoid(SLOPE * (theta - difficulty));
}

export function updateMastery(
  prev: ConceptMastery | undefined,
  score: number,
  difficulty: number,
  familiarity: Familiarity,
  now: number,
): ConceptMastery {
  const theta = thetaOf(prev, familiarity);
  const n = prev?.n ?? 0;
  const k = n < K_EARLY_ATTEMPTS ? K_EARLY : K_LATE;
  const next = theta + k * (score - pCorrect(theta, difficulty));
  return { theta: clamp(next, THETA_MIN, THETA_MAX), n: n + 1, lastSeen: now };
}

export function isMastered(m: ConceptMastery | undefined): boolean {
  return (
    !!m &&
    m.n >= MASTERY_MIN_ATTEMPTS &&
    pCorrect(m.theta, MASTERY_REFERENCE_DIFFICULTY) >= MASTERY_P_THRESHOLD
  );
}

export function reviewDue(m: ConceptMastery | undefined, now: number): boolean {
  return !!m && isMastered(m) && now - m.lastSeen > REVIEW_AFTER_MS;
}
/** Engine summary for the work model's dynamic context (design-plan §7.3, §9.1). */
import type { EngineSummary, GateContext } from "@/lib/contracts/engine";
import { rollingAccuracy, targetDifficulty } from "./difficulty";
import { valueThreshold } from "./guardrails";
import { isMastered, reviewDue } from "./mastery";

export const SUMMARY_RECENT_OUTCOMES = 3;

export function summarize(ctx: GateContext): EngineSummary {
  const { state, mastery, settings, familiarity, now } = ctx;
  const recent = state.recentOutcomes;
  return {
    guardrails: { ...settings.guardrails },
    valueThreshold: valueThreshold(settings),
    targetDifficulty: {
      firstExposure: targetDifficulty(undefined, "first_exposure", familiarity, recent),
      practice: targetDifficulty(undefined, "practice", familiarity, recent),
    },
    // Matches the gate: review-due concepts are left out so Claude may quiz them again.
    masteredConcepts: Object.keys(mastery)
      .filter((c) => isMastered(mastery[c]) && !reviewDue(mastery[c], now))
      .sort(),
    conceptsSinceBoss: [...state.conceptsSinceBoss],
    rollingAccuracy: rollingAccuracy(recent),
    recentOutcomes: recent
      .slice(-SUMMARY_RECENT_OUTCOMES)
      .map((o) => ({ concept: o.concept, type: o.type, score: o.score })),
  };
}
/** The gate: code decides whether Claude's candidate moment is shown (design-plan §7.1, principle P8). */
import type { DifficultyKind, GateContext, GateDecision } from "@/lib/contracts/engine";
import type { LearningMomentInput } from "@/lib/contracts/moment";
import { targetDifficulty } from "./difficulty";
import { capsExceeded, valueThreshold } from "./guardrails";
import { isMastered, reviewDue } from "./mastery";

/** Candidates this far (or further) from the target difficulty are off the challenge band (design-plan §7.1). */
export const OFF_BAND_DISTANCE = 2;

/** A top-value moment that prevents a costly mistake may bypass the value threshold and caps. */
export function isBreakthrough(c: LearningMomentInput): boolean {
  return c.costly_mistake && c.learning_value === 5;
}

export function gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision {
  const { state, mastery, settings, familiarity, now } = ctx;
  const breakthrough = isBreakthrough(candidate);
  const m = mastery[candidate.concept];

  if (state.pendingMomentId !== undefined) return { action: "skip", reason: "one_at_a_time" };

  if (candidate.learning_value < valueThreshold(settings) && !breakthrough) {
    return { action: "skip", reason: "low_value" };
  }

  if (isMastered(m) && !reviewDue(m, now)) return { action: "skip", reason: "mastered" };

  const kind: DifficultyKind = candidate.first_exposure || !m ? "first_exposure" : "practice";
  const target = targetDifficulty(m, kind, familiarity, state.recentOutcomes);
  if (Math.abs(candidate.difficulty - target) >= OFF_BAND_DISTANCE) return { action: "skip", reason: "off_band" };

  const { enabled, mode } = settings.guardrails;
  if (enabled && !breakthrough && capsExceeded(state, mode, now)) {
    return mode === "strict" ? { action: "defer", reason: "cap" } : { action: "skip", reason: "cap" };
  }

  return { action: "show" };
}
/** Small numeric helpers shared by the engine modules. */

export const sigmoid = (x: number): number => 1 / (1 + Math.exp(-x));

export const logit = (p: number): number => Math.log(p / (1 - p));

export const clamp = (x: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, x));

/** Tolerance for comparing averages of fractional scores (e.g. 0.6 + 0.6 + …) against thresholds. */
export const EPSILON = 1e-9;

