import { describe, expect, it } from "vitest";
import { summarize } from "./summary";
import { ctx, DAY, outcomes, settings, stateWith, T0 } from "./test-helpers";

describe("summarize", () => {
  it("summarises a fresh session", () => {
    expect(summarize(ctx())).toEqual({
      guardrails: { enabled: false, mode: "balanced" },
      valueThreshold: 4,
      targetDifficulty: { firstExposure: 1, practice: 1 },
      masteredConcepts: [],
      conceptsSinceBoss: [],
      rollingAccuracy: null,
      recentOutcomes: [],
    });
  });

  it("reports the strict threshold and familiarity-based targets", () => {
    const s = summarize(ctx({ settings: settings({ enabled: true, mode: "strict" }), familiarity: "comfortable" }));
    expect(s.valueThreshold).toBe(5);
    expect(s.guardrails).toEqual({ enabled: true, mode: "strict" });
    expect(s.targetDifficulty).toEqual({ firstExposure: 2, practice: 2 });
  });

  it("lists mastered concepts, sorted, excluding unmastered and review-due ones", () => {
    const s = summarize(
      ctx({
        mastery: {
          zeta: { theta: 5, n: 2, lastSeen: T0 },
          alpha: { theta: 5, n: 4, lastSeen: T0 },
          weak: { theta: 3, n: 4, lastSeen: T0 },
          stale: { theta: 5, n: 4, lastSeen: T0 - DAY - 1 },
        },
      }),
    );
    expect(s.masteredConcepts).toEqual(["alpha", "zeta"]);
  });

  it("includes rolling accuracy, the last 3 outcomes, and concepts since boss", () => {
    const recent = outcomes([0, 1, 0.5, 1, 0.6, 1]);
    const s = summarize(ctx({ state: stateWith({ recentOutcomes: recent, conceptsSinceBoss: ["a", "b"] }) }));
    expect(s.rollingAccuracy).toBeCloseTo((1 + 0.5 + 1 + 0.6 + 1) / 5);
    expect(s.recentOutcomes).toEqual([
      { concept: "c", type: "decide", score: 1 },
      { concept: "c", type: "decide", score: 0.6 },
      { concept: "c", type: "decide", score: 1 },
    ]);
    expect(s.conceptsSinceBoss).toEqual(["a", "b"]);
  });

  it("applies the rolling adjustment to the advertised targets", () => {
    const hot = summarize(ctx({ familiarity: "comfortable", state: stateWith({ recentOutcomes: outcomes([1, 1, 1]) }) }));
    // comfortable practice raw 2.345 + 0.5 → 2.845 → 3
    expect(hot.targetDifficulty.practice).toBe(3);
  });
});
/** Fixtures shared by the engine tests (not imported by production code). */
import {
  initialEngineState,
  type EngineState,
  type GateContext,
  type GuardrailMode,
  type Outcome,
  type UserSettings,
} from "@/lib/contracts/engine";
import type { LearningMomentInput } from "@/lib/contracts/moment";

export const MIN = 60 * 1000;
export const DAY = 24 * 60 * MIN;
export const T0 = 1_760_000_000_000;

export function candidate(overrides: Partial<LearningMomentInput> = {}): LearningMomentInput {
  return {
    type: "decide",
    concept: "train_test_split",
    question: "Why hold out a test set?",
    ideal_answer: "To estimate generalisation on unseen data.",
    rubric: { key_points: ["unseen data"] },
    mc_fallback: { options: ["a", "b", "c"], correct_index: 0, why: ["x", "y", "z"] },
    difficulty: 1,
    first_exposure: true,
    learning_value: 4,
    value_reason: "core idea",
    costly_mistake: false,
    timing: "before_step",
    ...overrides,
  };
}

export function settings(guardrails?: { enabled: boolean; mode: GuardrailMode }): UserSettings {
  return {
    sound: true,
    volume: 0.4,
    theme: "frost",
    soundPack: "default",
    guardrails: guardrails ?? { enabled: false, mode: "balanced" },
  };
}

export function ctx(overrides: Partial<GateContext> = {}): GateContext {
  return {
    state: initialEngineState(),
    mastery: {},
    settings: settings(),
    familiarity: "some",
    now: T0,
    ...overrides,
  };
}

export function outcome(score: number, i = 0, concept = "c"): Outcome {
  return { momentId: `m${i}`, concept, type: "decide", score, at: T0 + i };
}

export function outcomes(scores: number[]): Outcome[] {
  return scores.map((s, i) => outcome(s, i));
}

export function stateWith(overrides: Partial<EngineState>): EngineState {
  return { ...initialEngineState(), ...overrides };
}

/** Deterministic PRNG (mulberry32) for simulation tests. */
export function seededRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/**
 * Pacing engine (design-plan §7, §12): pure, deterministic, and unit-tested.
 * Code paces, Claude creates (P8): Claude proposes moments; this module decides what is shown and how hard.
 */
import type { EngineApi } from "@/lib/contracts/engine";
import { bossDue, bossOutcome } from "./boss";
import { targetDifficulty } from "./difficulty";
import { gate } from "./gate";
import { levelFor, rewardsBetween } from "./levels";
import { isMastered, reviewDue, updateMastery } from "./mastery";
import { recordOutcome, recordShown, recordWorkTurn } from "./state";
import { summarize } from "./summary";
import { xpFor } from "./xp";

export const engine: EngineApi = {
  gate,
  updateMastery,
  targetDifficulty,
  isMastered,
  reviewDue,
  bossDue,
  bossOutcome,
  summarize,
  recordShown,
  recordOutcome,
  recordWorkTurn,
  xpFor,
  levelFor,
  rewardsBetween,
};

export { bossDue, bossOutcome } from "./boss";
export { rollingAccuracy, targetDifficulty, TARGET_SUCCESS } from "./difficulty";
export { gate, isBreakthrough } from "./gate";
export { CAPS, capsExceeded, valueThreshold } from "./guardrails";
export { LEVEL_REWARDS, levelFor, rewardsBetween } from "./levels";
export { isMastered, reviewDue, SCORE, scoreFor, updateMastery } from "./mastery";
export {
  recordBossFinished,
  recordBossStarted,
  recordOutcome,
  recordShown,
  recordSkipped,
  recordWorkTurn,
} from "./state";
export { summarize } from "./summary";
export { XP, xpFor } from "./xp";
/**
 * Dynamic per-turn context (docs/design-plan.md §9.1), sent as a mid-conversation system message right after
 * the turn's user message. Kept in history (append-only), so it is never edited after it is sent.
 */
import type { EngineSummary } from "@/lib/contracts/engine";
import type { Session } from "@/lib/contracts/session";
import { BOSS_MIN_CONCEPTS } from "@/lib/engine/boss";

const MINUTE = 60_000;

export function sessionEndsAt(session: Pick<Session, "createdAt" | "intent">): number {
  return session.createdAt + session.intent.minutes * MINUTE;
}

export function timeLine(session: Pick<Session, "createdAt" | "intent">, now: number): string {
  const total = session.intent.minutes * MINUTE;
  const elapsed = now - session.createdAt;
  const left = Math.max(0, Math.ceil((total - elapsed) / MINUTE));
  if (elapsed >= total) return `Time: the planned ${session.intent.minutes} minutes are up. Finish the current step cleanly; the learner may wrap up or keep going.`;
  if (elapsed >= 0.8 * total) return `Time: ~2 minutes left: steer toward a milestone.`;
  return `Time: about ${left} of ${session.intent.minutes} minutes left.`;
}

const list = (xs: string[]) => (xs.length ? xs.join(", ") : "none");

export interface ContextInput {
  session: Pick<Session, "createdAt" | "intent" | "sketch">;
  summary: EngineSummary;
  now: number;
  /** Extra one-off notes for this turn (e.g. how to get the demo dataset). */
  notes?: string[];
}

export function renderContext({ session, summary, now, notes = [] }: ContextInput): string {
  const { intent, sketch } = session;
  const g = summary.guardrails;
  const lines = [
    "Co-learn context for this turn (from the app, not the learner):",
    `- Learner goal: ${intent.goal}`,
    `- Familiarity with this area: ${intent.familiarity}`,
    `- ${timeLine(session, now)}`,
    `- Moment gate: learning value >= ${summary.valueThreshold}. Target difficulty: ${summary.targetDifficulty.firstExposure} for a new concept, ${summary.targetDifficulty.practice} for practice.`,
    `- Guardrails: ${g.enabled ? `on (${g.mode}); fewer interruptions, so only propose your best moments` : "off"}`,
    `- Mastered concepts (don't quiz unless due for review): ${list(summary.masteredConcepts)}`,
    `- Concepts practised since the last boss: ${list(summary.conceptsSinceBoss)}`,
    `- Rolling accuracy: ${summary.rollingAccuracy === null ? "no graded answers yet" : `${Math.round(summary.rollingAccuracy * 100)}%`}`,
    `- Recent outcomes: ${summary.recentOutcomes.length ? summary.recentOutcomes.map((o) => `${o.concept} (${o.type}) ${o.score}`).join("; ") : "none"}`,
  ];
  if (new Set(summary.conceptsSinceBoss).size >= BOSS_MIN_CONCEPTS) {
    lines.push("- Enough concepts practised for a boss challenge: call milestone_reached at the next natural checkpoint (e.g. right after you report a result).");
  }
  if (sketch) {
    lines.push(`- Session sketch (a loose guide, not a curriculum): likely milestones: ${list(sketch.milestones)}`);
    if (sketch.conceptRadar.length) {
      lines.push(
        `- Concept radar: ${sketch.conceptRadar.map((c) => `${c.concept} (${c.likelyMomentType}): ${c.whyItMatters}`).join("; ")}`,
      );
    }
  }
  for (const note of notes) lines.push(`- ${note}`);
  return lines.join("\n");
}

export function demoDataNote(hasDemoFile: boolean): string {
  return hasDemoFile
    ? "Demo dataset: a customer-churn CSV has been uploaded to your sandbox with this message. Find it (e.g. with ls/find) and load it from the file."
    : "Demo dataset: no file is attached. First generate a realistic synthetic customer-churn dataset in the sandbox with a fixed seed and save it as churn.csv: ~5,000 rows, ~15% churn, columns customer_id, tenure_months, contract_type, monthly_charges, total_charges (a few missing), support_tickets_90d, payment_method, has_premium_support, last_login_days_ago, plan_tier, cancellation_request_date (mostly filled for churners: a planted leak), churned. Don't point out the leak or the missing values yourself; they're for the learner to discover. Then continue with the task.";
}

