  role,
  className = "",
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { selected?: boolean }) {
  const state = selected === undefined ? {} : role === "radio" ? { "aria-checked": selected } : { "aria-pressed": selected };
